const RECALL = GROUP.recall;
const ANSWERS = GROUP.answers;
const TOOLS = GROUP.tools;
const A = RECALL_TEXT.answer;
const P = RECALL_TEXT.prompt;
const W = RECALL_TEXT.writer;
const C = RECALL_TEXT.chronicle;

/** What the answers that print a message say of the placeholder that cites it. */
const CITE = v("cite", "the message's citation: its number and the start of its text's hash, as [#412 a3f9c27e]. Agents copy it into the chronicle and chronicle_check reads it back, so keep it as it is", true);
const WHEN = v("when", "when it was sent, as When a message was sent writes it; nothing where Lumiverse gives no time");
const QUERIES = "What to look for: one query or several, each answered on its own. Names and rare words find the most.";
const FROM = "Only messages from this number on.";
const TO = "Only messages up to this number.";
const SPEAKER = "Only messages of this speaker: a name as the chat shows it, or user or assistant.";
const REGEX = "true: text is a regular expression (JavaScript's, case-insensitive), matched within one line. Keep it simple: a repeat (*, +, {n,m}) follows one character or class, never a group, and an alternative holds one of * and + at most.";

/** A tool's argument text that has placeholders: `toolTexts` writes the ones that have none. */
const arg = (tool: string, name: string, text: string, vars: TextDef["vars"]): TextDef => ({ id: toolArgId(tool, name), group: TOOLS, label: `${tool}: ${name}`, note: `The description of ${tool}'s ${name} argument.`, text, vars });

